import 'package:dio/dio.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../auth/auth_controller.dart';\nimport '../../core/network/api_client.dart';\n\nfinal sellerRepositoryProvider = Provider<SellerRepository>((ref) => SellerRepository());\n\nclass SellerRepository {\n  SellerRepository({Dio? dio}) : _dio = dio ?? dioProvider.dio;\n  final Dio _dio;\n\n  Future<List<Map<String, dynamic>>> fetchProducts() async {\n    final response = await _dio.get('/products/seller');\n    final data = response.data;\n    final raw = data is List ? data : data is Map ? data['products'] : null;\n    if (raw is! List) throw const FormatException('فهرست کالاهای فروشنده نامعتبر است');\n    return raw.whereType<Map>().map(Map<String, dynamic>.from).toList();\n  }\n}\n\nclass SellerPage extends ConsumerStatefulWidget {\n  const SellerPage({super.key});\n  @override\n  ConsumerState<SellerPage> createState() => _SellerPageState();\n}\n\nclass _SellerPageState extends ConsumerState<SellerPage> {\n  bool loading = true;\n  String? error;\n  List<Map<String, dynamic>> products = [];\n\n  @override\n  void initState() { super.initState(); _load(); }\n\n  Future<void> _load() async {\n    setState(() { loading = true; error = null; });\n    try {\n      final user = ref.read(authControllerProvider).valueOrNull;\n      final role = user?['role']?.toString();\n      if (role != 'seller' && role != 'admin') {\n        if (mounted) setState(() { products = []; loading = false; });\n        return;\n      }\n      final items = await ref.read(sellerRepositoryProvider).fetchProducts();\n      if (!mounted) return;\n      setState(() { products = items; loading = false; });\n    } catch (e) {\n      if (!mounted) return;\n      setState(() { error = networkErrorMessage(e); loading = false; });\n    }\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final user = ref.watch(authControllerProvider).valueOrNull;\n    final role = user?['role']?.toString();\n    final isSeller = role == 'seller' || role == 'admin';\n    return Scaffold(\n      appBar: AppBar(title: const Text('فروشگاه من'), actions: [IconButton(onPressed: loading ? null : _load, icon: const Icon(Icons.refresh))]),\n      body: RefreshIndicator(\n        onRefresh: _load,\n        child: ListView(\n          physics: const AlwaysScrollableScrollPhysics(),\n          padding: const EdgeInsets.all(20),\n          children: [\n            Card(child: ListTile(leading: const Icon(Icons.storefront_outlined), title: Text(user?['name']?.toString() ?? 'فروشگاه من'), subtitle: Text(isSeller ? 'مدیریت ویترین و کالاها' : 'حساب شما هنوز فروشنده نیست'))),\n            const SizedBox(height: 16),\n            if (!isSeller) const Card(child: ListTile(leading: Icon(Icons.add_business_outlined), title: Text('ثبت فروشگاه'), subtitle: Text('برای شروع فروش، فروشگاه خود را ثبت کنید.')))\n            else if (loading) const Center(child: Padding(padding: EdgeInsets.all(32), child: CircularProgressIndicator()))\n            else if (error != null) Card(child: ListTile(leading: const Icon(Icons.error_outline), title: const Text('دریافت کالاها ناموفق بود'), subtitle: Text(error!), trailing: IconButton(onPressed: _load, icon: const Icon(Icons.refresh))))\n            else if (products.isEmpty) const Card(child: ListTile(leading: Icon(Icons.inventory_2_outlined), title: Text('هنوز کالایی ثبت نکرده‌اید'), subtitle: Text('اولین کالا را ثبت کنید تا در کی‌داره دیده شود.')))\n            else ...[\n              Text('کالاهای من (${products.length})', style: Theme.of(context).textTheme.titleMedium),\n              const SizedBox(height: 8),\n              ...products.map((p) => Card(child: ListTile(title: Text(p['name']?.toString() ?? 'کالای بدون نام'), subtitle: Text('${p['price'] ?? 'قیمت توافقی'} • ${p['status'] ?? 'نامشخص'}')))),\n            ],\n          ],\n        ),\n      ),\n    );\n  }\n}